CREATE SCHEMA IF NOT EXISTS annota;
CREATE TABLE IF NOT EXISTS annota.users (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS annota.projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, owner_id text NOT NULL REFERENCES annota.users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS annota.members (project_id uuid REFERENCES annota.projects(id), user_id text REFERENCES annota.users(id), role text NOT NULL CHECK(role IN ('owner','manager','annotator','reviewer')), PRIMARY KEY(project_id,user_id));
CREATE TABLE IF NOT EXISTS annota.invites (code_hash text PRIMARY KEY, project_id uuid NOT NULL REFERENCES annota.projects(id), role text NOT NULL CHECK(role IN ('manager','annotator','reviewer')), created_by text NOT NULL, expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', used_by text);
CREATE TABLE IF NOT EXISTS annota.media (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES annota.projects(id), object_key text NOT NULL UNIQUE, name text NOT NULL, mime text NOT NULL, bytes bigint NOT NULL CHECK(bytes>0), created_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS annota.tasks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES annota.projects(id), assignee_id text, submitted_by text, modality text NOT NULL CHECK(modality IN ('audio','video','image')), difficulty text NOT NULL DEFAULT 'normal' CHECK(difficulty IN ('easy','normal','hard')), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','pending','approved','returned','disputed')), version integer NOT NULL DEFAULT 1, payload jsonb NOT NULL, media_id uuid REFERENCES annota.media(id), submission_count integer NOT NULL DEFAULT 0, return_count integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS tasks_project_index ON annota.tasks(project_id,status);
CREATE TABLE IF NOT EXISTS annota.events (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, task_id uuid NOT NULL REFERENCES annota.tasks(id), actor_id text NOT NULL, kind text NOT NULL, meta jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS annota.sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id text NOT NULL, task_id uuid NOT NULL REFERENCES annota.tasks(id), started_at timestamptz NOT NULL DEFAULT now(), heartbeat_at timestamptz NOT NULL DEFAULT now(), ended_at timestamptz, seconds numeric NOT NULL DEFAULT 0 CHECK(seconds>=0));
CREATE UNIQUE INDEX IF NOT EXISTS one_active_session_per_user ON annota.sessions(user_id) WHERE ended_at IS NULL;
ALTER TABLE annota.sessions ADD COLUMN IF NOT EXISTS work_type text NOT NULL DEFAULT 'annotation' CHECK(work_type IN ('annotation','review'));
CREATE TABLE IF NOT EXISTS annota.batches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES annota.projects(id), created_by text NOT NULL, reviewer_a text NOT NULL, reviewer_b text NOT NULL, field text NOT NULL, rate numeric NOT NULL, seed text NOT NULL, strata jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), CHECK(reviewer_a<>reviewer_b));
CREATE TABLE IF NOT EXISTS annota.samples (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), batch_id uuid NOT NULL REFERENCES annota.batches(id), task_id uuid NOT NULL REFERENCES annota.tasks(id), revision bigint NOT NULL, submission integer NOT NULL DEFAULT 1, snapshot jsonb NOT NULL, stratum text NOT NULL, outcome text NOT NULL DEFAULT 'open' CHECK(outcome IN ('open','pass','fail','disputed','stale')), arbitration jsonb);
ALTER TABLE annota.samples ADD COLUMN IF NOT EXISTS submission integer NOT NULL DEFAULT 1;
ALTER TABLE annota.samples ADD COLUMN IF NOT EXISTS arbitration jsonb;
CREATE UNIQUE INDEX IF NOT EXISTS one_sample_per_submission ON annota.samples(task_id,revision,submission);
CREATE UNIQUE INDEX IF NOT EXISTS sample_once_per_batch ON annota.samples(batch_id,task_id);
CREATE TABLE IF NOT EXISTS annota.votes (sample_id uuid NOT NULL REFERENCES annota.samples(id), reviewer_id text NOT NULL, verdict text NOT NULL CHECK(verdict IN ('pass','fail')), note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(sample_id,reviewer_id));
ALTER TABLE annota.batches ADD COLUMN IF NOT EXISTS rule_version text NOT NULL DEFAULT 'annota-qc/1';
